files.content:
- if (Get-Process agent) { "ok" }
+ $fresh = (Get-Item out.log).LastWriteTime -gt (Get-Date).AddMinutes(-30)
+ if ($fresh) { "ok" } else { "stalled" }

+ if ($ageSeconds -lt 240) { return 'starting' }  # no verdict yet
  if (-not $connected) { Restart-Service }

- if (Get-Process -Id $savedPid -ErrorAction SilentlyContinue) { 'alive' }
+ $p = Get-Process -Id $savedPid -ErrorAction SilentlyContinue
+ if ($p -and $p.StartTime -eq $savedStart) { 'alive' }

+ # 5:00 daily: walk the real delivery path with a probe that sends nothing
+ Write-Probe -NoRecipient
+ if ((Get-Date).DayOfWeek -eq 'Sunday') { Send-RealTestMessage }

  param([switch]$DryRun)
+ if ($DryRun) { Write-Output "would write $path"; return }
  Set-Content $path $result
